x,y=sp.symbols('x y')
P=sp.Function('P')(x,y); Q=sp.Function('Q')(x,y)
# represent forms as dict: sorted tuple of indices -> coeff; wedge with sign
def wedge_basis(i,I):
    if i in I: return 0,None
    L=list(I)+[i]; L2=[i]+list(I)
    s=sorted(L2); perm=[L2.index(v) for v in s]
    inv=sum(1 for a in range(len(perm)) for b in range(a+1,len(perm)) if perm[a]>perm[b])
    return (-1)**inv,tuple(s)
vars_=[x,y]
def d(form):
    out={}
    for I,c in form.items():
        for j,v in enumerate(vars_):
            s,J=wedge_basis(j,I)
            if J is None: continue
            out[J]=out.get(J,0)+s*sp.diff(c,v)
    return out
w={(0,):P,(1,):Q}
dw=d(w)
